    "meaning": "梁国一户杨家的孩子九岁，非常聪明。孔君平去拜访他父亲，父亲不在，就叫出孩子。孩子摆上果子招待，果中有杨梅。孔君平指着杨梅对孩子说：这是你家的果子。孩子马上回答：没听说孔雀是先生您家的鸟。",
