    "title": "登高（杜甫）",
    "body": "风急天高猿啸哀，渚清沙白鸟飞回。无边落木萧萧下，不尽长江滚滚来。万里悲秋常作客，百年多病独登台。艰难苦恨繁霜鬓，潦倒新停浊酒杯。",
    "meaning": "风急天高，猿声哀鸣；水清沙白，鸟儿盘旋。无边的落叶萧萧而下，不尽的长江滚滚而来。漂泊万里，悲秋常作客；一生多病，独自登台。艰难苦恨使白发增多，穷困潦倒又刚停了酒杯。",
