    "body": "我的妈妈的样子，我闭上眼都能画出来。因为温柔，每天清晨给我做早饭，夜里还陪我写作业。那次我发烧，她一夜没睡，用湿毛巾一遍遍敷我的额头，这样的事常常发生。我想对她说：您辛苦了，我永远爱您，我想把它写进日记，永远留着。我忽然有点想哭，可又觉得没什么可哭的，只是心里涨得满满的，装不下别的东西了。我这才知道，别人对我的好从来不是理所当然的，只是他们愿意，才一直默默做着。这件事就这样过去了，像一滴水落进土里，看不见了，可我知道它一直在那里，养着我。",
