    "title": "《我的爸爸》（11）",
    "body": "我最想写的人，是我的爸爸。他是个憨厚的人，周末常带我去球场，教我带球射门。记得比赛输了躲着抹泪，他递来水拍拍头说尽力就好，那一刻我忽然长大了。他教我摔倒了就爬起来，这话我一直记着，长大以后我也要这样对待爱我的人。那一瞬间时间好像慢了下来，周围的声音都退远了，只剩下眼前这一幕，清清楚楚地留在心里。从那以后我看东西的眼光变了一点，不再只看表面，也愿意多问一句为什么、多想一层。往后的日子还长，我想我会记得这一天，记得当时的光、当时的声音，和当时心里那点热。",
    "analysis": "以生活细节写爸爸，抓住\"憨厚\"的特点，由事及情，语言质朴、中心明确，是适合同龄人模仿的写人/记事短文。",
