    "body": "我的爷爷的样子，我闭上眼都能画出来。他是个慈祥的人，总在院子里种花，还教我认各种草药的名字。记得下雨天他撑伞送我上学，伞总偏向我这边，那一刻我忽然长大了。爷爷的爱像细雨，悄悄润着我的心，我想把它写进日记，永远留着。我忽然有点想哭，可又觉得没什么可哭的，只是心里涨得满满的，装不下别的东西了。我这才知道，别人对我的好从来不是理所当然的，只是他们愿意，才一直默默做着。这件事就这样过去了，像一滴水落进土里，看不见了，可我知道它一直在那里，养着我。",
    "analysis": "以生活细节写爷爷，抓住\"慈祥\"的特点，由事及情，语言质朴、中心明确，是适合同龄人模仿的写人/记事短文。",
    "meta": "优秀作文",
