    "body": "说起我的爷爷，我心里就涌起一股暖意。他是个慈祥的人，总在院子里种花，还教我认各种草药的名字。记得下雨天他撑伞送我上学，伞总偏向我这边，那一刻我忽然长大了。爷爷的爱像细雨，悄悄润着我的心，这就是我家最暖的样子。那一瞬间时间好像慢了下来，周围的声音都退远了，只剩下眼前这一幕，清清楚楚地留在心里。从那以后我看东西的眼光变了一点，不再只看表面，也愿意多问一句为什么、多想一层。往后的日子还长，我想我会记得这一天，记得当时的光、当时的声音，和当时心里那点热。",
