    "title": "《我的奶奶》（31）",
    "body": "我最想写的人，是我的奶奶。她是个勤劳的人，天不亮就起来熬粥，把家里收拾得干干净净。记得我忘带文具，她跑着追到校门口递给我，那一刻我忽然长大了。奶奶的手很粗糙，却给了我最多的温暖，长大以后我也要这样对待爱我的人。当时我脸有点热，想说什么又咽了回去，后来才发现，那种说不出口的感觉才是最真的。如今再想起它，我不再只是欢喜或难过，而是多了几分明白，这大概就是它留给我的东西。我把本子合上，抬头看了看天，觉得明天大概会和今天不一样，又好像会一样好。",
