    "body": "我的语文老师的样子，我闭上眼都能画出来。他是个认真的人，批改作文特别细，好词好句都用红笔圈出来。记得我总写不好比喻，她指着梧桐叶教我观察，那一刻我忽然长大了。原来文字是有温度的，写作也可以很开心，我想把它写进日记，永远留着。我站在原地愣了几秒，忽然明白有些好是说不出口的，只能记在心里，留着以后慢慢想。这件事过去很久了，可它像一颗小石子落进水里，波纹一直没散，我也渐渐懂了一点从前不懂的道理。我轻轻呼出一口气，心里说：好，就这样吧，我记住了。",
