    "body": "我最想写的人，是我的同桌。热心的我的同桌总是我有不懂的题，他总抢着讲给我听。运动会我摔倒，他第一个冲过来扶我，这份心意我记了好久。同桌像个小太阳，照亮了我的每一天，长大以后我也要这样对待爱我的人。当时我脸有点热，想说什么又咽了回去，后来才发现，那种说不出口的感觉才是最真的。如今再想起它，我不再只是欢喜或难过，而是多了几分明白，这大概就是它留给我的东西。我把本子合上，抬头看了看天，觉得明天大概会和今天不一样，又好像会一样好。",
    "analysis": "以生活细节写同桌，抓住\"热心\"的特点，由事及情，语言质朴、中心明确，是适合同龄人模仿的写人/记事短文。",
    "meta": "优秀作文",
    "grade": "G1",
