    "title": "《我的同桌》（80）",
    "body": "在我们家，我的同桌是最让我牵挂的人。她是个热心的人，我有不懂的题，他总抢着讲给我听。记得运动会我摔倒，他第一个冲过来扶我，那一刻我忽然长大了。同桌像个小太阳，照亮了我的每一天。原来最平凡的陪伴，最珍贵。我忽然有点想哭，可又觉得没什么可哭的，只是心里涨得满满的，装不下别的东西了。我这才知道，别人对我的好从来不是理所当然的，只是他们愿意，才一直默默做着。这件事就这样过去了，像一滴水落进土里，看不见了，可我知道它一直在那里，养着我。",
