    "title": "《我家的小猫》（81）",
    "body": "我最想写的人，是我家的小猫。他是个淘气的人，爱追着自己的尾巴转圈，还爬上书架拨弄书。记得它把毛线团滚得到处都是，却歪着头装无辜，那一刻我忽然长大了。看着它熟睡的样子，我觉得烦恼都没了，长大以后我也要这样对待爱我的人。那一刻我心里像被温水泡过一样，说不出的软和，连呼吸都放轻了，生怕惊动了眼前这点好。我后来才想明白，很多事不在于做得多漂亮，而在于你有没有认真对待，有没有把心放进去。窗外的树又绿了一层，风一吹就沙沙地响，我坐在桌前写下这些，心里安安静静的。",
