    "body": "我家的小狗的样子，我闭上眼都能画出来。因为忠诚，每天放学它在门口摇尾巴迎接我。我难过时它趴在我脚边，用湿鼻子蹭我的手，这样的事常常发生。它是我最好的伙伴，陪我长大，我想把它写进日记，永远留着。我偷偷看了他一眼，又赶紧低下头，心里却像有一群小鸟扑棱棱地飞起来，怎么也按不住。我把这段记忆小心地收着，它不惊天动地，却在我心里占了一个谁也不能替代的位置。如果时间能倒回去，我还是愿意再走一遍那条路，再听一遍那句话，再做一次同样的选择。",
