    "body": "在我们家，一次爬山是最让我牵挂的人。因为难忘，和爸爸一起爬上山顶看日出。半路我腿软想放弃，他拉着我说再坚持一步，这样的事常常发生。站上山顶那刻，我懂了坚持的力量。原来最平凡的陪伴，最珍贵。我偷偷看了他一眼，又赶紧低下头，心里却像有一群小鸟扑棱棱地飞起来，怎么也按不住。我把这段记忆小心地收着，它不惊天动地，却在我心里占了一个谁也不能替代的位置。如果时间能倒回去，我还是愿意再走一遍那条路，再听一遍那句话，再做一次同样的选择。",
