    "title": "《快乐的春节》（134）",
    "body": "快乐的春节的样子，我闭上眼都能画出来。他是个热闹的人，全家包饺子、贴春联、放烟花。记得爷爷给我压岁钱，说愿我岁岁平安，那一刻我忽然长大了。团圆的味道，是一年里最暖的时光，我想把它写进日记，永远留着。我嘴上没说什么，心里却悄悄给它记了一笔，想着以后遇到差不多的事，也要这样做。原来长大不是忽然发生的，是在这样一件件小事里，悄悄地、一点一点地完成的。愿以后的我，还能像当时那样，肯为一朵花停下来，肯为一个人多走几步路。",
