    "body": "在我们家，雨后校园是最让我牵挂的人。因为清新，雨停后我和同学去操场踩水洼。树叶挂着水珠，蜗牛慢慢爬过石阶，这样的事常常发生。雨后的世界，像被洗过的画。原来最平凡的陪伴，最珍贵。我站在原地愣了几秒，忽然明白有些好是说不出口的，只能记在心里，留着以后慢慢想。这件事过去很久了，可它像一颗小石子落进水里，波纹一直没散，我也渐渐懂了一点从前不懂的道理。我轻轻呼出一口气，心里说：好，就这样吧，我记住了。这感觉很轻，却很实在。",
