    "title": "《雨后校园》（173）",
    "body": "说起雨后校园，我心里就涌起一股暖意。清新的雨后校园总是雨停后我和同学去操场踩水洼。树叶挂着水珠，蜗牛慢慢爬过石阶，这份心意我记了好久。雨后的世界，像被洗过的画，这就是我家最暖的样子。那种高兴不吵不闹，只是从心里一点点漫上来，让我走路都比平时轻快了几分。这件事教会我，慢一点没关系，怕一点也没关系，只要还愿意往前走，路就一直在脚下。这些平常的小事拼在一起，就是我的日子，普通，却是独一份的、谁也不能替我过的日子。",
