    "title": "《我的妈妈》（10）（重2）",
    "body": "我的妈妈的样子，我闭上眼都能画出来。因为温柔，每天清晨给我做早饭，夜里还陪我写作业。那次我发烧，她一夜没睡，用湿毛巾一遍遍敷我的额头，这样的事常常发生。我想对她说：您辛苦了，我永远爱您，长大以后我也要这样对待爱我的人。我偷偷看了他一眼，又赶紧低下头，心里却像有一群小鸟扑棱棱地飞起来，怎么也按不住。我把这段记忆小心地收着，它不惊天动地，却在我心里占了一个谁也不能替代的位置。如果时间能倒回去，我还是愿意再走一遍那条路，再听一遍那句话，再做一次同样的选择。",
