    "body": "在我们家，我的爷爷是最让我牵挂的人。他是个慈祥的人，总在院子里种花，还教我认各种草药的名字。记得下雨天他撑伞送我上学，伞总偏向我这边，那一刻我忽然长大了。爷爷的爱像细雨，悄悄润着我的心，长大以后我也要这样对待爱我的人。我偷偷看了他一眼，又赶紧低下头，心里却像有一群小鸟扑棱棱地飞起来，怎么也按不住。我把这段记忆小心地收着，它不惊天动地，却在我心里占了一个谁也不能替代的位置。如果时间能倒回去，我还是愿意再走一遍那条路，再听一遍那句话，再做一次同样的选择。",
