    "title": "A Sunny Morning",
    "en": "I wake up at seven every morning when the sun shines through my window. First, I wash my face and brush my teeth. Then I put on my school uniform and walk downstairs. My mother has already prepared breakfast for me. I eat an egg, drink a glass of milk, and say \"Good morning\" to my family. After breakfast, I pack my schoolbag with books, pens, and a small water bottle. I check the clock on the wall and leave home on time. The morning air is fresh and the birds are singing in the trees. I feel happy and ready to start a new day at school.",
    "zh": "每天早上七点，阳光照进我的窗户，我就醒了。我先洗脸刷牙，然后穿上校服下楼。妈妈已经为我准备好了早餐。我吃一个鸡蛋，喝一杯牛奶，并向家人说“早上好”。早饭后，我把课本、笔和一个小水壶装进书包。我看看墙上的钟，准时出门。早晨的空气清新，鸟儿在树上唱歌。我感到开心，准备好在学校开始新的一天。",
