    "en": "After school, I like to help my mother with housework. First, I fold the clean clothes and put them in the right drawers. Then I water the green plants on the balcony and wipe the dust off the table. Sometimes I help to set the table for dinner. My mother always smiles and says, \"You are such a helpful child.\" Doing chores makes me feel proud and strong. I learn to take care of my own things and help others, too. A tidy home gives everyone a happy mood, and small hands can make a big difference in the family.",
    "zh": "放学后，我喜欢帮妈妈做家务。我先把干净的衣服叠好，放进相应的抽屉，然后给阳台上的绿植浇水，擦掉桌子上的灰尘。有时我还帮忙摆放晚餐的餐具。妈妈总是笑着说：“你真是个爱帮忙的孩子。”做家务让我感到自豪和坚强。我学会照顾自己的东西，也帮助别人。整洁的家让每个人心情愉快，小手也能在家庭中发挥大作用。",
