    "title": "My Classroom",
    "en": "My classroom is on the third floor of our school building. It is a bright and clean room with six big windows. There are thirty-two desks in the room, and they are arranged in four rows. At the front of the classroom stands a large blackboard and a smart TV. On the wall, I can see the school motto, a world map, and a class timetable. My teacher, Miss Lin, is kind and patient. She always encourages us to ask questions. I love my classroom because it is the place where I learn new things, make friends, and grow a little every day.",
    "zh": "我的教室在学校教学楼的三楼。房间明亮整洁，有六扇大窗户。教室里摆着三十二张课桌，排成四排。教室前面有一块大黑板和一台智能电视。墙上挂着校训、世界地图和班级课程表。我的林老师既亲切又有耐心，总是鼓励我们多提问。我喜欢我的教室，因为这是让我每天学新知识、交朋友、慢慢成长的地方。",
