    "en": "My family is small but full of warmth, and every evening our little flat turns into the busiest and happiest place I know. My father leaves home early with a heavy bag, and when he comes back at night he still finds time to ask me about my day at school. Every Saturday morning we clean the house together, and my job is to wipe the table while my brother makes the beds badly and laughs about it. I did not finish everything, but I finished more than I expected. Last winter I had a high fever at night, and my mother sat by my bed with a wet towel, changing it again and again until the morning light came. We are not a rich family, and our holidays are simple, but my parents always find a way to make a small trip feel like a great adventure. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
