    "title": "My Family (12)",
    "en": "When people ask me what my family is like, I always say that we are ordinary people living an ordinary life with a lot of love. We are not a rich family, and our holidays are simple, but my parents always find a way to make a small trip feel like a great adventure. My grandmother lives with us, and her slow, gentle voice can calm me down faster than anything else in the world. After that I helped to tidy the room, and it did not take long at all. Every Saturday morning we clean the house together, and my job is to wipe the table while my brother makes the beds badly and laughs about it. Last winter I had a high fever at night, and my mother sat by my bed with a wet towel, changing it again and again until the morning light came. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "别人问我家是什么样，我总说：我们是普通人，过着普通的日子，却有很多很多的爱。我家并不富裕，假期也简单，可爸妈总有办法让一次小小的出游变成一场大冒险。奶奶和我们住在一起，她缓慢温和的声音，比什么都更能让我安静下来。之后我帮着收拾了房间，其实并没有花多久。每周六早上我们一起打扫，我擦桌子，弟弟铺床铺得歪歪扭扭，还笑个不停。去年冬天我夜里发高烧，妈妈坐在床边用湿毛巾一遍遍给我敷额头，一直到天亮。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
    "category": "Family",
