    "title": "My School (14)",
    "en": "My school is not very big, but there is always something happening in the classroom, on the playground or under the trees by the gate. Our Chinese teacher writes beautifully on the blackboard, and she always reads our compositions aloud when we do well, which makes us sit up straighter. On the playground we play football, jump rope and chase each other until the bell calls us back, red-faced and out of breath. I put the little thing in my bag so that I could look at it again later. Last term I failed a spelling test and felt like hiding under the desk, but my deskmate pushed a note towards me that said: next time we practise together. The last day of term is always strange, because we are happy about the holiday and sad about saying goodbye at the same time. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "我的学校不算大，可教室里、操场上、校门口的树下，总有事情在发生。语文老师的字写得漂亮，我们写得好时她总会朗读我们的作文，我们就坐得更直。操场上我们踢球、跳绳、互相追逐，直到铃声把我们叫回去，个个满脸通红、气喘吁吁。我把那个小东西放进书包，好以后还能再看看它。上学期我拼写测验不及格，恨不得躲到桌子底下，同桌却推来一张纸条：下次我们一起练。学期的最后一天总是很奇怪，我们一边为假期高兴，一边又为告别难过。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
