    "title": "My School (15)",
    "en": "I still remember my first day at school, when I held my mother's hand so tightly that my fingers turned white. On the playground we play football, jump rope and chase each other until the bell calls us back, red-faced and out of breath. Last term I failed a spelling test and felt like hiding under the desk, but my deskmate pushed a note towards me that said: next time we practise together. The next morning I got up a little earlier and did it again by myself. The last day of term is always strange, because we are happy about the holiday and sad about saying goodbye at the same time. Our Chinese teacher writes beautifully on the blackboard, and she always reads our compositions aloud when we do well, which makes us sit up straighter. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "我还记得上学的第一天，我紧紧抓着妈妈的手，手指都发白了。操场上我们踢球、跳绳、互相追逐，直到铃声把我们叫回去，个个满脸通红、气喘吁吁。上学期我拼写测验不及格，恨不得躲到桌子底下，同桌却推来一张纸条：下次我们一起练。第二天早上我起得早了一点，自己又做了一遍。学期的最后一天总是很奇怪，我们一边为假期高兴，一边又为告别难过。语文老师的字写得漂亮，我们写得好时她总会朗读我们的作文，我们就坐得更直。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
