    "title": "My School (22)",
    "en": "My school is not very big, but there is always something happening in the classroom, on the playground or under the trees by the gate. At lunch we carry our trays to the table by the window, and we trade pieces of chicken for pieces of fish like small businessmen. On the playground we play football, jump rope and chase each other until the bell calls us back, red-faced and out of breath. I keep that day in my mind because nothing about it was special, and that is why I like it. Last term I failed a spelling test and felt like hiding under the desk, but my deskmate pushed a note towards me that said: next time we practise together. The last day of term is always strange, because we are happy about the holiday and sad about saying goodbye at the same time. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "我的学校不算大，可教室里、操场上、校门口的树下，总有事情在发生。午饭时我们把餐盘端到窗边的桌子，像小商人一样用鸡块换鱼块。操场上我们踢球、跳绳、互相追逐，直到铃声把我们叫回去，个个满脸通红、气喘吁吁。我一直记着那一天，因为它没有什么特别之处，而这正是我喜欢它的原因。上学期我拼写测验不及格，恨不得躲到桌子底下，同桌却推来一张纸条：下次我们一起练。学期的最后一天总是很奇怪，我们一边为假期高兴，一边又为告别难过。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
