    "en": "I still remember my first day at school, when I held my mother's hand so tightly that my fingers turned white. On the playground we play football, jump rope and chase each other until the bell calls us back, red-faced and out of breath. Last term I failed a spelling test and felt like hiding under the desk, but my deskmate pushed a note towards me that said: next time we practise together. My teacher wrote one short sentence on my notebook and smiled at me. The last day of term is always strange, because we are happy about the holiday and sad about saying goodbye at the same time. At lunch we carry our trays to the table by the window, and we trade pieces of chicken for pieces of fish like small businessmen. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
