    "title": "My Pet Cat (27)",
    "en": "I have always loved animals, and I believe that a person who is kind to a small creature is usually kind to people too. My cat sleeps in a square of sunlight on the floor, and when the sun moves, she moves with it without ever opening her eyes. Feeding an animal is a promise, because it cannot open the fridge or ask a neighbour for help when you forget. I put the little thing in my bag so that I could look at it again later. Animals cannot speak, but they tell you everything with their eyes, their tails and the way they lean against your leg. Some people think animals are toys, but they are living creatures with feelings, habits and their own small plans. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "我一直喜欢动物，我相信对小生命温柔的人，对人通常也温柔。我的猫睡在地板上一块方方的阳光里，太阳挪动，她闭着眼也跟着挪。喂养动物是一个承诺，因为它不会开冰箱，也不会在你忘记时向邻居求助。我把那个小东西放进书包，好以后还能再看看它。动物不会说话，可它们用眼睛、尾巴和靠在你腿上的方式告诉你一切。有人把动物当玩具，可它们是有感情、有习惯、有自己的小打算的生命。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
