    "title": "My Pet Dog (42)",
    "en": "When I watch an animal, I always feel that it is busy with its own important life, just like us. Some people think animals are toys, but they are living creatures with feelings, habits and their own small plans. The birds on the balcony come every morning for the rice we leave, and they argue loudly about who should eat first. When I look back now, I think the best part was simply being there. Feeding an animal is a promise, because it cannot open the fridge or ask a neighbour for help when you forget. I keep that day in my mind because nothing about it was special, and that is why I like it. Animals cannot speak, but they tell you everything with their eyes, their tails and the way they lean against your leg. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "我看着动物时，总觉得它们正忙着自己重要的一生，和我们一样。有人把动物当玩具，可它们是有感情、有习惯、有自己的小打算的生命。阳台上的鸟每天早上来吃我们留的米，还为谁先吃大声吵架。现在回想起来，我觉得最好的部分就是当时在场。喂养动物是一个承诺，因为它不会开冰箱，也不会在你忘记时向邻居求助。我一直记着那一天，因为它没有什么特别之处，而这正是我喜欢它的原因。动物不会说话，可它们用眼睛、尾巴和靠在你腿上的方式告诉你一切。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
