    "title": "My Pet Dog (44)",
    "en": "There are animals all around us, in the park, on the rooftops and even under the stones by the river, waiting for someone to notice them. When my cat was ill last year, I stayed beside her and watched her breathe, and I understood for the first time what worry really feels like. Animals cannot speak, but they tell you everything with their eyes, their tails and the way they lean against your leg. The next morning I got up a little earlier and did it again by myself. Some people think animals are toys, but they are living creatures with feelings, habits and their own small plans. My cat sleeps in a square of sunlight on the floor, and when the sun moves, she moves with it without ever opening her eyes. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "我们身边到处是动物：公园里、屋顶上，甚至河边的石头下面，它们等着有人发现。去年我的猫生病，我守在旁边看它呼吸，第一次明白担心是什么感觉。动物不会说话，可它们用眼睛、尾巴和靠在你腿上的方式告诉你一切。第二天早上我起得早了一点，自己又做了一遍。有人把动物当玩具，可它们是有感情、有习惯、有自己的小打算的生命。我的猫睡在地板上一块方方的阳光里，太阳挪动，她闭着眼也跟着挪。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
