    "title": "My Pet Dog (47)",
    "en": "I have always loved animals, and I believe that a person who is kind to a small creature is usually kind to people too. My dog waits by the door every afternoon, and the moment he hears my footsteps he starts spinning like a small brown wheel. When my cat was ill last year, I stayed beside her and watched her breathe, and I understood for the first time what worry really feels like. I did not finish everything, but I finished more than I expected. Animals cannot speak, but they tell you everything with their eyes, their tails and the way they lean against your leg. Some people think animals are toys, but they are living creatures with feelings, habits and their own small plans. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
