    "title": "My Pet Dog (51)",
    "en": "I have always loved animals, and I believe that a person who is kind to a small creature is usually kind to people too. The goldfish in our tank swims slowly round and round, and sometimes it stops and looks at me as if it is thinking about something important. When my cat was ill last year, I stayed beside her and watched her breathe, and I understood for the first time what worry really feels like. I keep that day in my mind because nothing about it was special, and that is why I like it. Animals cannot speak, but they tell you everything with their eyes, their tails and the way they lean against your leg. Some people think animals are toys, but they are living creatures with feelings, habits and their own small plans. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "我一直喜欢动物，我相信对小生命温柔的人，对人通常也温柔。鱼缸里的金鱼慢慢游来游去，有时停下来看我，好像在思考什么大事。去年我的猫生病，我守在旁边看它呼吸，第一次明白担心是什么感觉。我一直记着那一天，因为它没有什么特别之处，而这正是我喜欢它的原因。动物不会说话，可它们用眼睛、尾巴和靠在你腿上的方式告诉你一切。有人把动物当玩具，可它们是有感情、有习惯、有自己的小打算的生命。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
    "category": "Animals",
