    "title": "A Sunny Day (63)",
    "en": "Some people hate rainy days, but I have learned that every kind of weather brings something you cannot get in sunshine. Last week the rain was so heavy that the road turned into a river, and my father carried me across on his back. Weather is not good or bad; it is only different, and the same rain that ruins a picnic makes the garden green. My father said that small things often teach us the biggest lessons. When the wind gets strong, umbrellas turn inside out, and people run with their bags over their heads, laughing and shouting. I love the ten minutes after a heavy rain, when the clouds break and the sun makes every puddle shine like a small mirror. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "有人讨厌雨天，可我发现每种天气都会带来晴天得不到的东西。上周雨大得路变成了河，爸爸把我背了过去。天气没有好坏，只是不同；同一场雨毁了野餐，却让花园变绿。爸爸说，小事情常常教给我们最大的道理。风大时伞都被吹翻，人们把包顶在头上边跑边笑边喊。我喜欢大雨后的十分钟，云裂开，太阳把每个水洼照得像小镜子。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
