    "title": "A Sunny Day (64)",
    "en": "In my city the four seasons take turns politely, but sometimes summer and winter argue and the weather changes three times in one day. Weather is not good or bad; it is only different, and the same rain that ruins a picnic makes the garden green. When the wind gets strong, umbrellas turn inside out, and people run with their bags over their heads, laughing and shouting. After that I helped to tidy the room, and it did not take long at all. I love the ten minutes after a heavy rain, when the clouds break and the sun makes every puddle shine like a small mirror. Last week the rain was so heavy that the road turned into a river, and my father carried me across on his back. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "我这城市四季轮流得很有礼貌，可有时夏冬争吵，一天里天气变三回。天气没有好坏，只是不同；同一场雨毁了野餐，却让花园变绿。风大时伞都被吹翻，人们把包顶在头上边跑边笑边喊。之后我帮着收拾了房间，其实并没有花多久。我喜欢大雨后的十分钟，云裂开，太阳把每个水洼照得像小镜子。上周雨大得路变成了河，爸爸把我背了过去。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
