    "title": "A Sunny Day (65)",
    "en": "The weather changes the colour of my street, the sound of my steps and even the way I feel in the morning. On snowy mornings the city is silent, and every sound is soft, as if the whole world had put on thick socks. I love the ten minutes after a heavy rain, when the clouds break and the sun makes every puddle shine like a small mirror. I had to try twice before I got it right, and the second time felt easy. Last week the rain was so heavy that the road turned into a river, and my father carried me across on his back. Weather is not good or bad; it is only different, and the same rain that ruins a picnic makes the garden green. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "天气会改变我这条街的颜色、我脚步声的响动，甚至我早上的心情。下雪的早晨城市很静，所有声音都变软了，好像全世界都穿上了厚袜子。我喜欢大雨后的十分钟，云裂开，太阳把每个水洼照得像小镜子。我试了两次才做对，第二次就觉得轻松了。上周雨大得路变成了河，爸爸把我背了过去。天气没有好坏，只是不同；同一场雨毁了野餐，却让花园变绿。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
