    "en": "The weather changes the colour of my street, the sound of my steps and even the way I feel in the morning. When the first drops hit the dusty ground, the whole street smells of wet earth, and everybody stops to breathe it in. In summer my mother puts a bowl of water on the balcony for the birds, and by noon it is always half empty. I put the little thing in my bag so that I could look at it again later. Last week the rain was so heavy that the road turned into a river, and my father carried me across on his back. Weather is not good or bad; it is only different, and the same rain that ruins a picnic makes the garden green. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
