    "zh": "有人讨厌雨天，可我发现每种天气都会带来晴天得不到的东西。上周雨大得路变成了河，爸爸把我背了过去。天气没有好坏，只是不同；同一场雨毁了野餐，却让花园变绿。回家的路上，我把那天上午发生的事都告诉了妈妈。第一滴雨落在积灰的地上，整条街都是湿土的味道，人人都停下来深吸一口。夏天妈妈在阳台放一碗水给鸟喝，到中午总是少了一半。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
