    "title": "A Rainy Day (72)",
    "en": "In my city the four seasons take turns politely, but sometimes summer and winter argue and the weather changes three times in one day. Weather is not good or bad; it is only different, and the same rain that ruins a picnic makes the garden green. When the first drops hit the dusty ground, the whole street smells of wet earth, and everybody stops to breathe it in. We shared what we had with the others, and there was enough for everyone. In summer my mother puts a bowl of water on the balcony for the birds, and by noon it is always half empty. Last week the rain was so heavy that the road turned into a river, and my father carried me across on his back. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "我这城市四季轮流得很有礼貌，可有时夏冬争吵，一天里天气变三回。天气没有好坏，只是不同；同一场雨毁了野餐，却让花园变绿。第一滴雨落在积灰的地上，整条街都是湿土的味道，人人都停下来深吸一口。我们把自己的东西分给别人，结果每个人都够了。夏天妈妈在阳台放一碗水给鸟喝，到中午总是少了一半。上周雨大得路变成了河，爸爸把我背了过去。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
