    "title": "A Rainy Day (74)",
    "en": "I like watching the sky before it rains, because the clouds gather slowly like a big grey family meeting above the roofs. In summer my mother puts a bowl of water on the balcony for the birds, and by noon it is always half empty. Last week the rain was so heavy that the road turned into a river, and my father carried me across on his back. That evening I wrote three lines about it in my diary before bed. Weather is not good or bad; it is only different, and the same rain that ruins a picnic makes the garden green. On very hot days the road shines like water, and the trees stand still as if they were too tired to move. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "我喜欢看雨前的天空，云慢慢聚拢，像一大片灰色的家庭会议开在屋顶上。夏天妈妈在阳台放一碗水给鸟喝，到中午总是少了一半。上周雨大得路变成了河，爸爸把我背了过去。那天晚上睡前，我在日记里为它写了三行字。天气没有好坏，只是不同；同一场雨毁了野餐，却让花园变绿。特别热的时候路面亮得像水，树一动不动，像累得挪不动。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
