    "title": "A Rainy Day (77)",
    "en": "The weather changes the colour of my street, the sound of my steps and even the way I feel in the morning. When the wind gets strong, umbrellas turn inside out, and people run with their bags over their heads, laughing and shouting. In summer my mother puts a bowl of water on the balcony for the birds, and by noon it is always half empty. I keep that day in my mind because nothing about it was special, and that is why I like it. Last week the rain was so heavy that the road turned into a river, and my father carried me across on his back. Weather is not good or bad; it is only different, and the same rain that ruins a picnic makes the garden green. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
