    "en": "I like watching the sky before it rains, because the clouds gather slowly like a big grey family meeting above the roofs. In summer my mother puts a bowl of water on the balcony for the birds, and by noon it is always half empty. Last week the rain was so heavy that the road turned into a river, and my father carried me across on his back. My teacher wrote one short sentence on my notebook and smiled at me. Weather is not good or bad; it is only different, and the same rain that ruins a picnic makes the garden green. When the wind gets strong, umbrellas turn inside out, and people run with their bags over their heads, laughing and shouting. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
