    "title": "My Favorite Food (79)",
    "en": "Food is more than something we eat; in my family it is the way we say good morning, welcome home and I love you. My grandmother's noodles are thin and springy, and she says the secret is resting the dough three times before cutting it. On cold days a bowl of soup warms me from the inside, and I can feel it travel all the way down like good news. I put the little thing in my bag so that I could look at it again later. Once I tried to cook noodles alone and put in three times too much salt, and we ended up eating bread for dinner. Cooking is not difficult; it only asks you to pay attention, and paying attention is a useful habit everywhere. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "食物不只是吃的东西；在我家，它是我们说早安、欢迎回家和我爱你的方式。奶奶的面条又细又筋道，她说秘诀是切之前让面团醒三次。冷天里一碗汤从里面暖起来，我能感觉它像好消息一样一路往下走。我把那个小东西放进书包，好以后还能再看看它。有一次我自己煮面，盐放了整整三倍，结果我们晚饭吃的是面包。做饭不难，它只要求你用心，而用心在任何地方都是好习惯。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
