    "title": "My Favorite Food (84)",
    "en": "Every city has a smell that belongs only to it, and in my city that smell is hot oil, spring onions and fresh bread. On cold days a bowl of soup warms me from the inside, and I can feel it travel all the way down like good news. Once I tried to cook noodles alone and put in three times too much salt, and we ended up eating bread for dinner. That evening I wrote three lines about it in my diary before bed. Cooking is not difficult; it only asks you to pay attention, and paying attention is a useful habit everywhere. My father makes egg fried rice with yesterday's rice, and it always tastes better than the fresh kind, which makes no sense to me. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "每座城市都有只属于它的味道，我这座城市的味道是热油、葱和新面包。冷天里一碗汤从里面暖起来，我能感觉它像好消息一样一路往下走。有一次我自己煮面，盐放了整整三倍，结果我们晚饭吃的是面包。那天晚上睡前，我在日记里为它写了三行字。做饭不难，它只要求你用心，而用心在任何地方都是好习惯。爸爸用隔夜饭做蛋炒饭，总比新米饭做的好吃，我怎么也想不通。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
