    "title": "Healthy Fruits (92)",
    "en": "Every city has a smell that belongs only to it, and in my city that smell is hot oil, spring onions and fresh bread. On cold days a bowl of soup warms me from the inside, and I can feel it travel all the way down like good news. Once I tried to cook noodles alone and put in three times too much salt, and we ended up eating bread for dinner. We walked home slowly, and the street looked different in the evening light. Cooking is not difficult; it only asks you to pay attention, and paying attention is a useful habit everywhere. Our breakfast is simple: porridge, pickles, an egg and a glass of warm milk, and it has not changed in years. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
