    "title": "Healthy Fruits (93)",
    "en": "I was a picky child, and it took my grandmother ten years and a hundred dishes to teach me how to eat with joy. Once I tried to cook noodles alone and put in three times too much salt, and we ended up eating bread for dinner. Cooking is not difficult; it only asks you to pay attention, and paying attention is a useful habit everywhere. I drew a small picture of it and gave the picture to my best friend. Our breakfast is simple: porridge, pickles, an egg and a glass of warm milk, and it has not changed in years. On cold days a bowl of soup warms me from the inside, and I can feel it travel all the way down like good news. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "我曾是个挑食的孩子，奶奶用了十年、一百道菜，才教会我快乐地吃饭。有一次我自己煮面，盐放了整整三倍，结果我们晚饭吃的是面包。做饭不难，它只要求你用心，而用心在任何地方都是好习惯。我把它画成一张小画，送给了我最好的朋友。我们的早餐很简单：粥、咸菜、一个鸡蛋和一杯热牛奶，多年没变。冷天里一碗汤从里面暖起来，我能感觉它像好消息一样一路往下走。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
