    "title": "Healthy Fruits (99)",
    "en": "Food is more than something we eat; in my family it is the way we say good morning, welcome home and I love you. My father makes egg fried rice with yesterday's rice, and it always tastes better than the fresh kind, which makes no sense to me. In summer we eat cold noodles with cucumber and vinegar, and the whole family makes a happy noise while eating. I did not finish everything, but I finished more than I expected. Once I tried to cook noodles alone and put in three times too much salt, and we ended up eating bread for dinner. Cooking is not difficult; it only asks you to pay attention, and paying attention is a useful habit everywhere. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
