    "title": "My Room (106)",
    "en": "Home is not a big place, but it is the only place where I can be lazy, silly and completely myself. Every evening the light in the living room turns warm and yellow, and the noise of the day slowly becomes quiet. Once the water pipe broke and the floor was covered with water, and we spent the whole evening drying it with towels and laughing. The next morning I got up a little earlier and did it again by myself. Our neighbours are old and quiet, but they always save the first oranges from their tree for us. The living room has a big sofa that has lost its shape, because my brother and I have jumped on it for years. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "家不是个大地方，却是唯一让我可以偷懒、犯傻、完全做自己的地方。每天傍晚客厅的灯变得暖黄，白天的喧闹慢慢安静下来。有一次水管破了，满地是水，我们用毛巾擦了一整晚，还笑个不停。第二天早上我起得早了一点，自己又做了一遍。我们的邻居是安静的老人，可他们总把树上的第一批橘子留给我们。客厅的沙发早没了形状，因为我和弟弟在上面跳了好多年。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
