    "title": "My Room (108)",
    "en": "We moved into this flat when I was six, and every corner of it still remembers something that happened to us. Our neighbours are old and quiet, but they always save the first oranges from their tree for us. The living room has a big sofa that has lost its shape, because my brother and I have jumped on it for years. We shared what we had with the others, and there was enough for everyone. Every evening the light in the living room turns warm and yellow, and the noise of the day slowly becomes quiet. Once the water pipe broke and the floor was covered with water, and we spent the whole evening drying it with towels and laughing. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
