    "en": "Our flat is on the fifth floor, and from the window I can see a row of trees, a busy road and a small piece of sky. My desk stands by the window, and its surface is covered with pencil marks, small stickers and a cup full of pens that never work. Every evening the light in the living room turns warm and yellow, and the noise of the day slowly becomes quiet. I did not finish everything, but I finished more than I expected. Once the water pipe broke and the floor was covered with water, and we spent the whole evening drying it with towels and laughing. Our neighbours are old and quiet, but they always save the first oranges from their tree for us. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
