    "title": "My Room (111)",
    "en": "The moment I turn the key and push the door open, the smell of dinner tells me what kind of evening we are going to have. Once the water pipe broke and the floor was covered with water, and we spent the whole evening drying it with towels and laughing. Our neighbours are old and quiet, but they always save the first oranges from their tree for us. I learned the names of a few things I had never noticed before. My desk stands by the window, and its surface is covered with pencil marks, small stickers and a cup full of pens that never work. Every evening the light in the living room turns warm and yellow, and the noise of the day slowly becomes quiet. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "钥匙一转、门一推，晚饭的香味就告诉我，今晚会是怎样的一个晚上。有一次水管破了，满地是水，我们用毛巾擦了一整晚，还笑个不停。我们的邻居是安静的老人，可他们总把树上的第一批橘子留给我们。我记住了几样以前从没注意过的东西的名字。我的书桌在窗边，桌面满是铅笔印、小贴纸，还有一个装满写不出字的笔的杯子。每天傍晚客厅的灯变得暖黄，白天的喧闹慢慢安静下来。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
