    "title": "My Room (117)",
    "en": "Our flat is on the fifth floor, and from the window I can see a row of trees, a busy road and a small piece of sky. On the balcony we grow green onions in old pots, and my father talks to them every morning as if they were his little students. Every evening the light in the living room turns warm and yellow, and the noise of the day slowly becomes quiet. I had to try twice before I got it right, and the second time felt easy. Once the water pipe broke and the floor was covered with water, and we spent the whole evening drying it with towels and laughing. Our neighbours are old and quiet, but they always save the first oranges from their tree for us. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "我家在五楼，从窗口能看见一排树、一条热闹的马路和一小块天空。阳台上我们用旧花盆种葱，爸爸每天早上跟它们说话，好像在教小学生。每天傍晚客厅的灯变得暖黄，白天的喧闹慢慢安静下来。我试了两次才做对，第二次就觉得轻松了。有一次水管破了，满地是水，我们用毛巾擦了一整晚，还笑个不停。我们的邻居是安静的老人，可他们总把树上的第一批橘子留给我们。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
