    "title": "Going Shopping (119)",
    "en": "I am not a famous person and nothing exciting happens to me, but my small life has its own surprising stories. I have a small box where I keep ticket stubs, dried leaves and notes from friends, and it is the story of my year. Once I helped an old man carry his shopping upstairs and he gave me two apples, which tasted better than any I had bought. The next morning I got up a little earlier and did it again by myself. Small habits are powerful, because a page a day becomes a book and a minute a day becomes an hour. Getting up is the hardest part of my day, so I put my alarm clock on the other side of the room to force myself to stand up. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
