    "title": "Going Shopping (121)",
    "en": "Growing up feels slow while it is happening and very fast when you look back at it. Small habits are powerful, because a page a day becomes a book and a minute a day becomes an hour. Getting up is the hardest part of my day, so I put my alarm clock on the other side of the room to force myself to stand up. We shared what we had with the others, and there was enough for everyone. I have a small box where I keep ticket stubs, dried leaves and notes from friends, and it is the story of my year. Once I helped an old man carry his shopping upstairs and he gave me two apples, which tasted better than any I had bought. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "长大的时候觉得慢，回头看的时候又觉得很快。小习惯很有力量：每天一页就是一本书，每天一分钟就是一小时。起床是我一天中最难的部分，所以我把闹钟放到房间另一头，逼自己站起来。我们把自己的东西分给别人，结果每个人都够了。我有一个小盒子，装着票根、干叶子和朋友写的纸条，那就是我一年的故事。有一次我帮一位老人把菜提上楼，他给了我两个苹果，比买来的都好吃。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
    "category": "Life",
