    "title": "Going Shopping (122)",
    "en": "Ordinary days look boring on a calendar, but when I look closer, something interesting happens almost every hour. On the way to school I count red cars, and if I reach twenty before the gate, I tell myself it will be a good day. I have a small box where I keep ticket stubs, dried leaves and notes from friends, and it is the story of my year. I did not finish everything, but I finished more than I expected. Once I helped an old man carry his shopping upstairs and he gave me two apples, which tasted better than any I had bought. Small habits are powerful, because a page a day becomes a book and a minute a day becomes an hour. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "平常的日子在日历上很无聊，可仔细一看，几乎每个小时都有点有意思的事。上学路上我数红色的车，要是在校门前数到二十，我就告诉自己今天会顺利。我有一个小盒子，装着票根、干叶子和朋友写的纸条，那就是我一年的故事。我没有把所有事都做完，但做完的比预想的多。有一次我帮一位老人把菜提上楼，他给了我两个苹果，比买来的都好吃。小习惯很有力量：每天一页就是一本书，每天一分钟就是一小时。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
