    "title": "Going Shopping (123)",
    "en": "I am not a famous person and nothing exciting happens to me, but my small life has its own surprising stories. I have a small box where I keep ticket stubs, dried leaves and notes from friends, and it is the story of my year. Once I helped an old man carry his shopping upstairs and he gave me two apples, which tasted better than any I had bought. That evening I wrote three lines about it in my diary before bed. Small habits are powerful, because a page a day becomes a book and a minute a day becomes an hour. On the way to school I count red cars, and if I reach twenty before the gate, I tell myself it will be a good day. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "我不是名人，也没什么刺激的事发生在我身上，可我的小生活自有它出人意料的故事。我有一个小盒子，装着票根、干叶子和朋友写的纸条，那就是我一年的故事。有一次我帮一位老人把菜提上楼，他给了我两个苹果，比买来的都好吃。那天晚上睡前，我在日记里为它写了三行字。小习惯很有力量：每天一页就是一本书，每天一分钟就是一小时。上学路上我数红色的车，要是在校门前数到二十，我就告诉自己今天会顺利。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
