    "title": "Going Shopping (124)",
    "en": "Every morning I wake up at the same time, and yet no two days have ever been exactly the same. Once I helped an old man carry his shopping upstairs and he gave me two apples, which tasted better than any I had bought. Small habits are powerful, because a page a day becomes a book and a minute a day becomes an hour. I learned the names of a few things I had never noticed before. On the way to school I count red cars, and if I reach twenty before the gate, I tell myself it will be a good day. I have a small box where I keep ticket stubs, dried leaves and notes from friends, and it is the story of my year. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
