    "title": "A Trip to the Park (132)",
    "en": "Every morning I wake up at the same time, and yet no two days have ever been exactly the same. Once I helped an old man carry his shopping upstairs and he gave me two apples, which tasted better than any I had bought. Small habits are powerful, because a page a day becomes a book and a minute a day becomes an hour. I drew a small picture of it and gave the picture to my best friend. At night I write three lines in my diary, and even on a bad day I can usually find one line that is not so bad. I have a small box where I keep ticket stubs, dried leaves and notes from friends, and it is the story of my year. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "每天早上我在同一时间醒来，可从来没有两天是完全一样的。有一次我帮一位老人把菜提上楼，他给了我两个苹果，比买来的都好吃。小习惯很有力量：每天一页就是一本书，每天一分钟就是一小时。我把它画成一张小画，送给了我最好的朋友。晚上我在日记里写三行，即使是很糟的一天，通常也能找出一行不算太糟的。我有一个小盒子，装着票根、干叶子和朋友写的纸条，那就是我一年的故事。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
