    "title": "A Trip to the Park (134)",
    "en": "Ordinary days look boring on a calendar, but when I look closer, something interesting happens almost every hour. Getting up is the hardest part of my day, so I put my alarm clock on the other side of the room to force myself to stand up. Learning to tie my shoelaces took me three weeks, and I still remember the day it finally worked. I put the little thing in my bag so that I could look at it again later. Once I helped an old man carry his shopping upstairs and he gave me two apples, which tasted better than any I had bought. Small habits are powerful, because a page a day becomes a book and a minute a day becomes an hour. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "平常的日子在日历上很无聊，可仔细一看，几乎每个小时都有点有意思的事。起床是我一天中最难的部分，所以我把闹钟放到房间另一头，逼自己站起来。学系鞋带花了我三个星期，我还记得终于成功的那一天。我把那个小东西放进书包，好以后还能再看看它。有一次我帮一位老人把菜提上楼，他给了我两个苹果，比买来的都好吃。小习惯很有力量：每天一页就是一本书，每天一分钟就是一小时。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
