    "title": "A Trip to the Park (135)",
    "en": "I am not a famous person and nothing exciting happens to me, but my small life has its own surprising stories. Learning to tie my shoelaces took me three weeks, and I still remember the day it finally worked. Once I helped an old man carry his shopping upstairs and he gave me two apples, which tasted better than any I had bought. The next morning I got up a little earlier and did it again by myself. Small habits are powerful, because a page a day becomes a book and a minute a day becomes an hour. Getting up is the hardest part of my day, so I put my alarm clock on the other side of the room to force myself to stand up. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "我不是名人，也没什么刺激的事发生在我身上，可我的小生活自有它出人意料的故事。学系鞋带花了我三个星期，我还记得终于成功的那一天。有一次我帮一位老人把菜提上楼，他给了我两个苹果，比买来的都好吃。第二天早上我起得早了一点，自己又做了一遍。小习惯很有力量：每天一页就是一本书，每天一分钟就是一小时。起床是我一天中最难的部分，所以我把闹钟放到房间另一头，逼自己站起来。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
