    "title": "A Trip to the Park (137)",
    "en": "Growing up feels slow while it is happening and very fast when you look back at it. Small habits are powerful, because a page a day becomes a book and a minute a day becomes an hour. Getting up is the hardest part of my day, so I put my alarm clock on the other side of the room to force myself to stand up. We shared what we had with the others, and there was enough for everyone. Learning to tie my shoelaces took me three weeks, and I still remember the day it finally worked. Once I helped an old man carry his shopping upstairs and he gave me two apples, which tasted better than any I had bought. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
