    "title": "A Trip to the Park (138)",
    "en": "Ordinary days look boring on a calendar, but when I look closer, something interesting happens almost every hour. On the way to school I count red cars, and if I reach twenty before the gate, I tell myself it will be a good day. Learning to tie my shoelaces took me three weeks, and I still remember the day it finally worked. I did not finish everything, but I finished more than I expected. Once I helped an old man carry his shopping upstairs and he gave me two apples, which tasted better than any I had bought. Small habits are powerful, because a page a day becomes a book and a minute a day becomes an hour. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
