    "title": "A Trip to the Park (141)",
    "en": "Growing up feels slow while it is happening and very fast when you look back at it. Small habits are powerful, because a page a day becomes a book and a minute a day becomes an hour. On the way to school I count red cars, and if I reach twenty before the gate, I tell myself it will be a good day. Nobody said much for a moment, and then everybody started to laugh. Learning to tie my shoelaces took me three weeks, and I still remember the day it finally worked. I put the little thing in my bag so that I could look at it again later. Once I helped an old man carry his shopping upstairs and he gave me two apples, which tasted better than any I had bought. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "长大的时候觉得慢，回头看的时候又觉得很快。小习惯很有力量：每天一页就是一本书，每天一分钟就是一小时。上学路上我数红色的车，要是在校门前数到二十，我就告诉自己今天会顺利。有一小会儿谁也没说话，然后大家都笑了起来。学系鞋带花了我三个星期，我还记得终于成功的那一天。我把那个小东西放进书包，好以后还能再看看它。有一次我帮一位老人把菜提上楼，他给了我两个苹果，比买来的都好吃。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
