    "title": "A Trip to the Park (143)",
    "en": "I am not a famous person and nothing exciting happens to me, but my small life has its own surprising stories. Learning to tie my shoelaces took me three weeks, and I still remember the day it finally worked. Once I helped an old man carry his shopping upstairs and he gave me two apples, which tasted better than any I had bought. My teacher wrote one short sentence on my notebook and smiled at me. Small habits are powerful, because a page a day becomes a book and a minute a day becomes an hour. I learned the names of a few things I had never noticed before. My mother gives me the same advice every week: finish your homework first, then enjoy your time without worry. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "我不是名人，也没什么刺激的事发生在我身上，可我的小生活自有它出人意料的故事。学系鞋带花了我三个星期，我还记得终于成功的那一天。有一次我帮一位老人把菜提上楼，他给了我两个苹果，比买来的都好吃。老师在我的本子上写了一句短短的话，还朝我笑了笑。小习惯很有力量：每天一页就是一本书，每天一分钟就是一小时。我记住了几样以前从没注意过的东西的名字。妈妈每周都说同样的话：先做完作业，再安心地玩。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
