    "title": "My Birthday (144)",
    "en": "Festivals are the days when ordinary life puts on its best clothes and invites everybody to join in. Before Spring Festival we clean every corner, write red couplets and hang a paper cut on the window. My job is to put the sweets in a red box, and I always hide one extra for myself at the bottom. I put the little thing in my bag so that I could look at it again later. When I was small, I was afraid of the loud firecrackers, so my father covered my ears with his warm hands. After that I helped to tidy the room, and it did not take long at all. Festivals remind us who we belong to, and that is worth more than any present. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "节日就是平常生活穿上最好的衣服、邀请所有人参加的日子。春节前我们把每个角落打扫干净，写红对联，在窗上贴剪纸。我的任务是把糖果装进红盒子，我总在底下给自己多藏一颗。我把那个小东西放进书包，好以后还能再看看它。小时候我怕响亮的鞭炮，爸爸用温暖的手替我捂住耳朵。之后我帮着收拾了房间，其实并没有花多久。节日提醒我们属于谁，这比任何礼物都珍贵。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
