    "title": "My Birthday (145)",
    "en": "In my family, every festival has a smell, a colour and a job that belongs to me. My job is to put the sweets in a red box, and I always hide one extra for myself at the bottom. When I was small, I was afraid of the loud firecrackers, so my father covered my ears with his warm hands. The next morning I got up a little earlier and did it again by myself. Festivals remind us who we belong to, and that is worth more than any present. I drew a small picture of it and gave the picture to my best friend. Before Spring Festival we clean every corner, write red couplets and hang a paper cut on the window. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "在我家，每个节日都有一种味道、一种颜色，还有一件属于我的活儿。我的任务是把糖果装进红盒子，我总在底下给自己多藏一颗。小时候我怕响亮的鞭炮，爸爸用温暖的手替我捂住耳朵。第二天早上我起得早了一点，自己又做了一遍。节日提醒我们属于谁，这比任何礼物都珍贵。我把它画成一张小画，送给了我最好的朋友。春节前我们把每个角落打扫干净，写红对联，在窗上贴剪纸。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
