    "title": "My Birthday (146)",
    "en": "I love festivals not because of the food or the presents, but because everyone tries a little harder to be kind. When I was small, I was afraid of the loud firecrackers, so my father covered my ears with his warm hands. Festivals remind us who we belong to, and that is worth more than any present. On the way home I told my mother everything that had happened that morning. Before Spring Festival we clean every corner, write red couplets and hang a paper cut on the window. The next morning I got up a little earlier and did it again by myself. My job is to put the sweets in a red box, and I always hide one extra for myself at the bottom. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
