    "title": "My Birthday (147)",
    "en": "The best part of a festival is the night before, when everything is almost ready and the air is full of waiting. Festivals remind us who we belong to, and that is worth more than any present. Before Spring Festival we clean every corner, write red couplets and hang a paper cut on the window. We shared what we had with the others, and there was enough for everyone. My job is to put the sweets in a red box, and I always hide one extra for myself at the bottom. I did not finish everything, but I finished more than I expected. When I was small, I was afraid of the loud firecrackers, so my father covered my ears with his warm hands. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "节日最好的部分是前一天晚上，一切差不多准备好，空气里满是期待。节日提醒我们属于谁，这比任何礼物都珍贵。春节前我们把每个角落打扫干净，写红对联，在窗上贴剪纸。我们把自己的东西分给别人，结果每个人都够了。我的任务是把糖果装进红盒子，我总在底下给自己多藏一颗。我没有把所有事都做完，但做完的比预想的多。小时候我怕响亮的鞭炮，爸爸用温暖的手替我捂住耳朵。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
