    "title": "My Birthday (151)",
    "en": "The best part of a festival is the night before, when everything is almost ready and the air is full of waiting. Festivals remind us who we belong to, and that is worth more than any present. At Mid-Autumn Festival we sit on the balcony with mooncakes, and my grandmother tells the story of Chang'e again. Nobody said much for a moment, and then everybody started to laugh. My job is to put the sweets in a red box, and I always hide one extra for myself at the bottom. I put the little thing in my bag so that I could look at it again later. When I was small, I was afraid of the loud firecrackers, so my father covered my ears with his warm hands. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "节日最好的部分是前一天晚上，一切差不多准备好，空气里满是期待。节日提醒我们属于谁，这比任何礼物都珍贵。中秋我们端着月饼坐在阳台，奶奶又讲一遍嫦娥的故事。有一小会儿谁也没说话，然后大家都笑了起来。我的任务是把糖果装进红盒子，我总在底下给自己多藏一颗。我把那个小东西放进书包，好以后还能再看看它。小时候我怕响亮的鞭炮，爸爸用温暖的手替我捂住耳朵。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
