    "title": "My Birthday (156)",
    "en": "Festivals are the days when ordinary life puts on its best clothes and invites everybody to join in. On Lantern Festival we walk through the park with small lanterns and try to guess the riddles hanging on the wires. My job is to put the sweets in a red box, and I always hide one extra for myself at the bottom. I had to try twice before I got it right, and the second time felt easy. When I was small, I was afraid of the loud firecrackers, so my father covered my ears with his warm hands. When I look back now, I think the best part was simply being there. Festivals remind us who we belong to, and that is worth more than any present. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "节日就是平常生活穿上最好的衣服、邀请所有人参加的日子。元宵节我们提着小灯笼逛公园，猜挂在绳上的灯谜。我的任务是把糖果装进红盒子，我总在底下给自己多藏一颗。我试了两次才做对，第二次就觉得轻松了。小时候我怕响亮的鞭炮，爸爸用温暖的手替我捂住耳朵。现在回想起来，我觉得最好的部分就是当时在场。节日提醒我们属于谁，这比任何礼物都珍贵。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
