    "title": "Spring Is Coming (162)",
    "en": "Spring in my city arrives quietly, first as a smell in the air and then suddenly as a hundred shades of green. In summer we eat watermelon on the balcony with the light off, and the seeds go into a bowl for a competition. Last spring we planted sunflower seeds in a pot, and every morning I measured how much taller they had grown overnight. That evening I wrote three lines about it in my diary before bed. Each season takes something away and gives something else, which is why I can never say which one I like best. In summer the cicadas start at noon and do not stop until the light goes, and their noise becomes the background of our games. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "我这城市的春天来得很轻，先是一股气味，然后忽然变成上百种绿。夏天我们在关了灯的阳台上吃西瓜，瓜子吐进碗里比赛。去年春天我们在花盆里种向日葵，每天早上我都量它们一夜长高了多少。那天晚上睡前，我在日记里为它写了三行字。每个季节都带走一些、给予一些，所以我说不出最喜欢哪一个。夏天知了从中午叫到天黑，它们的噪音成了我们游戏的背景。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
