    "title": "Spring Is Coming (163)",
    "en": "Summer is loud and generous, giving us long days, cold watermelon and the freedom to stay outside after dinner. Last spring we planted sunflower seeds in a pot, and every morning I measured how much taller they had grown overnight. Each season takes something away and gives something else, which is why I can never say which one I like best. I learned the names of a few things I had never noticed before. In summer the cicadas start at noon and do not stop until the light goes, and their noise becomes the background of our games. In summer we eat watermelon on the balcony with the light off, and the seeds go into a bowl for a competition. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
