    "title": "Spring Is Coming (164)",
    "en": "Autumn is my favourite season, because it changes the whole street into a painting without asking anyone's permission. Each season takes something away and gives something else, which is why I can never say which one I like best. In summer the cicadas start at noon and do not stop until the light goes, and their noise becomes the background of our games. Nobody said much for a moment, and then everybody started to laugh. In summer we eat watermelon on the balcony with the light off, and the seeds go into a bowl for a competition. Last spring we planted sunflower seeds in a pot, and every morning I measured how much taller they had grown overnight. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
