    "zh": "每个季节都有自己的声音，闭上眼我不看日历也能分辨。去年春天我们在花盆里种向日葵，每天早上我都量它们一夜长高了多少。每个季节都带走一些、给予一些，所以我说不出最喜欢哪一个。我把它画成一张小画，送给了我最好的朋友。秋天叶子打着圈慢慢落下，孩子们捡最红的夹进书里。夏天我们在关了灯的阳台上吃西瓜，瓜子吐进碗里比赛。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
