    "title": "Summer Holiday (174)",
    "en": "Autumn is my favourite season, because it changes the whole street into a painting without asking anyone's permission. In summer we eat watermelon on the balcony with the light off, and the seeds go into a bowl for a competition. Last spring we planted sunflower seeds in a pot, and every morning I measured how much taller they had grown overnight. The next morning I got up a little earlier and did it again by myself. Each season takes something away and gives something else, which is why I can never say which one I like best. In winter my breath turns white in front of my face, and I draw pictures in the air that disappear at once. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
