    "title": "Summer Holiday (177)",
    "en": "Spring in my city arrives quietly, first as a smell in the air and then suddenly as a hundred shades of green. In spring the rain is thin and soft, and it makes the dust smell sweet instead of washing it away. In summer we eat watermelon on the balcony with the light off, and the seeds go into a bowl for a competition. I did not finish everything, but I finished more than I expected. Last spring we planted sunflower seeds in a pot, and every morning I measured how much taller they had grown overnight. Each season takes something away and gives something else, which is why I can never say which one I like best. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
