    "title": "Summer Holiday (181)",
    "en": "Every season has its own sound, and if I close my eyes I can tell which one it is without looking at the calendar. In spring the rain is thin and soft, and it makes the dust smell sweet instead of washing it away. In summer we eat watermelon on the balcony with the light off, and the seeds go into a bowl for a competition. I keep that day in my mind because nothing about it was special, and that is why I like it. Last spring we planted sunflower seeds in a pot, and every morning I measured how much taller they had grown overnight. Each season takes something away and gives something else, which is why I can never say which one I like best. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "每个季节都有自己的声音，闭上眼我不看日历也能分辨。春雨又细又轻，它不让尘土消失，反而让尘土变香。夏天我们在关了灯的阳台上吃西瓜，瓜子吐进碗里比赛。我一直记着那一天，因为它没有什么特别之处，而这正是我喜欢它的原因。去年春天我们在花盆里种向日葵，每天早上我都量它们一夜长高了多少。每个季节都带走一些、给予一些，所以我说不出最喜欢哪一个。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
    "category": "Seasons",
