    "title": "Autumn Leaves (185)",
    "en": "Winter makes everything simple: the trees are bare, the sky is pale, and people walk quickly with their shoulders up. In spring the buds appear overnight, and the next morning the birds sound as if they have been waiting all winter to sing. In autumn my mother buys chestnuts, and the warm paper bag in my hands smells like the whole season. I had to try twice before I got it right, and the second time felt easy. Last spring we planted sunflower seeds in a pot, and every morning I measured how much taller they had grown overnight. Each season takes something away and gives something else, which is why I can never say which one I like best. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
