    "zh": "每个季节都有自己的声音，闭上眼我不看日历也能分辨。去年春天我们在花盆里种向日葵，每天早上我都量它们一夜长高了多少。每个季节都带走一些、给予一些，所以我说不出最喜欢哪一个。回家的路上，我把那天上午发生的事都告诉了妈妈。夏天知了从中午叫到天黑，它们的噪音成了我们游戏的背景。秋天妈妈买栗子，手里热乎乎的纸袋闻起来就是整个季节。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
    "category": "Seasons",
