    "title": "Autumn Leaves (192)",
    "en": "Spring in my city arrives quietly, first as a smell in the air and then suddenly as a hundred shades of green. Each season takes something away and gives something else, which is why I can never say which one I like best. In autumn the leaves fall in slow circles, and children collect the reddest ones to press inside their books. We shared what we had with the others, and there was enough for everyone. In autumn my mother buys chestnuts, and the warm paper bag in my hands smells like the whole season. I did not finish everything, but I finished more than I expected. Last spring we planted sunflower seeds in a pot, and every morning I measured how much taller they had grown overnight. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "我这城市的春天来得很轻，先是一股气味，然后忽然变成上百种绿。每个季节都带走一些、给予一些，所以我说不出最喜欢哪一个。秋天叶子打着圈慢慢落下，孩子们捡最红的夹进书里。我们把自己的东西分给别人，结果每个人都够了。秋天妈妈买栗子，手里热乎乎的纸袋闻起来就是整个季节。我没有把所有事都做完，但做完的比预想的多。去年春天我们在花盆里种向日葵，每天早上我都量它们一夜长高了多少。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
