    "title": "Autumn Leaves (195)",
    "en": "Winter makes everything simple: the trees are bare, the sky is pale, and people walk quickly with their shoulders up. Last spring we planted sunflower seeds in a pot, and every morning I measured how much taller they had grown overnight. Each season takes something away and gives something else, which is why I can never say which one I like best. I learned the names of a few things I had never noticed before. In autumn the leaves fall in slow circles, and children collect the reddest ones to press inside their books. We walked home slowly, and the street looked different in the evening light. In autumn my mother buys chestnuts, and the warm paper bag in my hands smells like the whole season. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
