    "en": "Every season has its own sound, and if I close my eyes I can tell which one it is without looking at the calendar. In winter my breath turns white in front of my face, and I draw pictures in the air that disappear at once. In autumn my mother buys chestnuts, and the warm paper bag in my hands smells like the whole season. I had to try twice before I got it right, and the second time felt easy. Last spring we planted sunflower seeds in a pot, and every morning I measured how much taller they had grown overnight. Each season takes something away and gives something else, which is why I can never say which one I like best. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "每个季节都有自己的声音，闭上眼我不看日历也能分辨。冬天我呼出的气在面前变白，我在空中画画，立刻就消失。秋天妈妈买栗子，手里热乎乎的纸袋闻起来就是整个季节。我试了两次才做对，第二次就觉得轻松了。去年春天我们在花盆里种向日葵，每天早上我都量它们一夜长高了多少。每个季节都带走一些、给予一些，所以我说不出最喜欢哪一个。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
