    "title": "Winter Snow (203)",
    "en": "Summer is loud and generous, giving us long days, cold watermelon and the freedom to stay outside after dinner. Last spring we planted sunflower seeds in a pot, and every morning I measured how much taller they had grown overnight. Each season takes something away and gives something else, which is why I can never say which one I like best. I drew a small picture of it and gave the picture to my best friend. In spring the rain is thin and soft, and it makes the dust smell sweet instead of washing it away. That evening I wrote three lines about it in my diary before bed. In autumn my mother buys chestnuts, and the warm paper bag in my hands smells like the whole season. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "夏天喧闹又慷慨，给我们长长的白天、冰西瓜和晚饭后待在外面的自由。去年春天我们在花盆里种向日葵，每天早上我都量它们一夜长高了多少。每个季节都带走一些、给予一些，所以我说不出最喜欢哪一个。我把它画成一张小画，送给了我最好的朋友。春雨又细又轻，它不让尘土消失，反而让尘土变香。那天晚上睡前，我在日记里为它写了三行字。秋天妈妈买栗子，手里热乎乎的纸袋闻起来就是整个季节。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
