    "title": "My Favorite Sport (211)",
    "en": "Running is simple: you put one foot in front of the other until you surprise yourself. Last year our class lost every match, and yet we still trained every Tuesday, which I am now proud of. Sport teaches you to lose in front of people, which is a lesson that life repeats later anyway. On the way home I told my mother everything that had happened that morning. When I first started running, I could not finish one lap, and my legs felt like they belonged to someone else. The next morning I got up a little earlier and did it again by myself. The last five minutes of a match are the most honest, because nobody has the energy to pretend anymore. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "跑步很简单：把一只脚放到另一只前面，直到你让自己吃惊。去年我们班每场都输，可每周二仍然训练，现在我很为此骄傲。运动教你在众人面前输，这一课生活以后反正还会重复。回家的路上，我把那天上午发生的事都告诉了妈妈。刚开始跑步时我一圈都跑不完，腿像不属于自己。第二天早上我起得早了一点，自己又做了一遍。比赛最后五分钟最真实，因为谁都没力气再装了。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
