    "title": "My Favorite Sport (212)",
    "en": "Sport is the only subject where losing is part of the lesson and nobody thinks it is strange. Sport teaches you to lose in front of people, which is a lesson that life repeats later anyway. When I first started running, I could not finish one lap, and my legs felt like they belonged to someone else. We shared what we had with the others, and there was enough for everyone. The last five minutes of a match are the most honest, because nobody has the energy to pretend anymore. I did not finish everything, but I finished more than I expected. Last year our class lost every match, and yet we still trained every Tuesday, which I am now proud of. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "体育是唯一一门输了也算上课、没人觉得奇怪的科目。运动教你在众人面前输，这一课生活以后反正还会重复。刚开始跑步时我一圈都跑不完，腿像不属于自己。我们把自己的东西分给别人，结果每个人都够了。比赛最后五分钟最真实，因为谁都没力气再装了。我没有把所有事都做完，但做完的比预想的多。去年我们班每场都输，可每周二仍然训练，现在我很为此骄傲。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
