    "en": "I am not the strongest or the fastest in my class, but sport has taught me things that marks cannot measure. In our football team I am the smallest, so I learned to pass quickly instead of fighting for the ball. The last five minutes of a match are the most honest, because nobody has the energy to pretend anymore. I keep that day in my mind because nothing about it was special, and that is why I like it. Last year our class lost every match, and yet we still trained every Tuesday, which I am now proud of. Sport teaches you to lose in front of people, which is a lesson that life repeats later anyway. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
