    "title": "Reading Books (222)",
    "en": "A hobby is the part of my day that belongs to nobody else, and that is exactly why I love it. I draw comic stories about a cat who thinks he is a tiger, and my friends ask for the next page every week. At first I was bad at it, and being bad was uncomfortable, but I kept going because I liked it anyway. I put the little thing in my bag so that I could look at it again later. Last year I made a small book for my grandmother's birthday, with drawings and a story she had told me. A hobby is not a waste of time; it is how you find out what kind of person you are. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "爱好是我一天中不属于任何别人的部分，正因如此我才喜欢它。我画一只自以为老虎的猫的漫画，朋友每周都催下一话。一开始我很差，差得让人不舒服，可我还是继续，因为我就是喜欢。我把那个小东西放进书包，好以后还能再看看它。去年我给奶奶做了一本小书，画上画，写着她讲过的故事。爱好不是浪费时间，它是你发现自己是什么人的方式。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
