    "zh": "我试过很多爱好，每一个都留下了点什么，包括我放弃的那些。一开始我很差，差得让人不舒服，可我还是继续，因为我就是喜欢。去年我给奶奶做了一本小书，画上画，写着她讲过的故事。老师在我的本子上写了一句短短的话，还朝我笑了笑。爱好不是浪费时间，它是你发现自己是什么人的方式。我记住了几样以前从没注意过的东西的名字。我用纸箱做东西，房间常像个小型工厂。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
