    "title": "Reading Books (232)",
    "en": "Nobody pays me to draw, read or build things, and yet I keep doing it, which must mean it matters. Last year I made a small book for my grandmother's birthday, with drawings and a story she had told me. A hobby is not a waste of time; it is how you find out what kind of person you are. My father said that small things often teach us the biggest lessons. I build things out of cardboard boxes, and my room often looks like a small factory. My teacher wrote one short sentence on my notebook and smiled at me. At first I was bad at it, and being bad was uncomfortable, but I kept going because I liked it anyway. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
