    "title": "Reading Books (234)",
    "en": "A hobby is the part of my day that belongs to nobody else, and that is exactly why I love it. I collect leaves and press them in a heavy dictionary, and each one remembers a day and a place. At first I was bad at it, and being bad was uncomfortable, but I kept going because I liked it anyway. I had to try twice before I got it right, and the second time felt easy. Last year I made a small book for my grandmother's birthday, with drawings and a story she had told me. When I look back now, I think the best part was simply being there. A hobby is not a waste of time; it is how you find out what kind of person you are. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "爱好是我一天中不属于任何别人的部分，正因如此我才喜欢它。我收集叶子夹在厚字典里，每片都记得某一天、某个地方。一开始我很差，差得让人不舒服，可我还是继续，因为我就是喜欢。我试了两次才做对，第二次就觉得轻松了。去年我给奶奶做了一本小书，画上画，写着她讲过的故事。现在回想起来，我觉得最好的部分就是当时在场。爱好不是浪费时间，它是你发现自己是什么人的方式。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
