    "zh": "做爱好时时间很奇怪，一小时像五分钟。爱好不是浪费时间，它是你发现自己是什么人的方式。我画一只自以为老虎的猫的漫画，朋友每周都催下一话。我们把自己的东西分给别人，结果每个人都够了。我的爱好很安静，所以大家常忘了我在屋里，我暗自得意。我没有把所有事都做完，但做完的比预想的多。去年我给奶奶做了一本小书，画上画，写着她讲过的故事。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
