    "zh": "我试过很多爱好，每一个都留下了点什么，包括我放弃的那些。我的爱好很安静，所以大家常忘了我在屋里，我暗自得意。去年我给奶奶做了一本小书，画上画，写着她讲过的故事。我们慢慢走回家，傍晚的光线里街道看起来不一样了。爱好不是浪费时间，它是你发现自己是什么人的方式。回家的路上，我把那天上午发生的事都告诉了妈妈。我收集叶子夹在厚字典里，每片都记得某一天、某个地方。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
