    "title": "Music Time (252)",
    "en": "Nobody pays me to draw, read or build things, and yet I keep doing it, which must mean it matters. Last year I made a small book for my grandmother's birthday, with drawings and a story she had told me. A hobby is not a waste of time; it is how you find out what kind of person you are. I drew a small picture of it and gave the picture to my best friend. I collect leaves and press them in a heavy dictionary, and each one remembers a day and a place. That evening I wrote three lines about it in my diary before bed. My hobby is quiet, so people often forget I am in the room, which I secretly enjoy. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "没人付钱让我画画、读书或做东西，我却一直做，这说明它一定重要。去年我给奶奶做了一本小书，画上画，写着她讲过的故事。爱好不是浪费时间，它是你发现自己是什么人的方式。我把它画成一张小画，送给了我最好的朋友。我收集叶子夹在厚字典里，每片都记得某一天、某个地方。那天晚上睡前，我在日记里为它写了三行字。我的爱好很安静，所以大家常忘了我在屋里，我暗自得意。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
