    "title": "Music Time (253)",
    "en": "When I am doing my hobby, time behaves strangely and an hour feels like five minutes. A hobby is not a waste of time; it is how you find out what kind of person you are. I collect leaves and press them in a heavy dictionary, and each one remembers a day and a place. When I look back now, I think the best part was simply being there. My hobby is quiet, so people often forget I am in the room, which I secretly enjoy. I keep that day in my mind because nothing about it was special, and that is why I like it. Last year I made a small book for my grandmother's birthday, with drawings and a story she had told me. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
    "zh": "做爱好时时间很奇怪，一小时像五分钟。爱好不是浪费时间，它是你发现自己是什么人的方式。我收集叶子夹在厚字典里，每片都记得某一天、某个地方。现在回想起来，我觉得最好的部分就是当时在场。我的爱好很安静，所以大家常忘了我在屋里，我暗自得意。我一直记着那一天，因为它没有什么特别之处，而这正是我喜欢它的原因。去年我给奶奶做了一本小书，画上画，写着她讲过的故事。有一天下午我坐着不动看了十分钟，发现了三样走过一百次都没注意的东西。那一刻我又暖又有点不好意思，不知道手该往哪儿放。我学到了：勇敢不是不害怕，而是害怕的时候仍然往前走。所以下次同样的机会来时，我不会再犹豫那么久才答应。",
