    "en": "A hobby is the part of my day that belongs to nobody else, and that is exactly why I love it. I draw comic stories about a cat who thinks he is a tiger, and my friends ask for the next page every week. I once spent a whole weekend finishing a project, and on Sunday night I felt tired and very happy. I put the little thing in my bag so that I could look at it again later. Last year I made a small book for my grandmother's birthday, with drawings and a story she had told me. A hobby is not a waste of time; it is how you find out what kind of person you are. One afternoon I sat still for ten minutes and simply watched, and I noticed three things I had walked past a hundred times. At that moment I felt warm and a little shy, and I did not know where to put my hands. I learned that being brave does not mean you are not afraid; it means you go on even when you are. So now, whenever the same chance comes again, I will not wait so long before I say yes.",
